    'tip.legal.keep': 'Hvor lenge dere beholder det dere får, for hver type nettstedet har; personvernsiden sier det i alle designene',
    'tip.legal.keep.forms': 'Hvor lenge det besøkende sender gjennom skjemaene på sidene, beholdes. Ikke bestemt, sier personvernsiden det og ber leseren spørre',
