    'tip.legal.keep.orders': 'Hvor lenge bestillinger oppbevares, etter plikten dere har; «?» sier hvem som har hvilken. Ikke bestemt, så sier personvernsiden det og ber leseren spørre',
    'legal.cloudflare': 'Cloudflare teller besøkene',
    'tip.legal.cloudflare': 'Cloudflare legger sin egen besøkstelling på de publiserte sidene; personvernsiden forteller det',
    'hint.cloudflare.title': 'Cloudflares telling av besøk',
    'hint.cloudflare.1': 'Cloudflare slår på Web Analytics av seg selv for et domene på gratisplanen (fra 15. oktober 2025), og legger telleskriptet sitt inn i sidene på vei til den besøkende. Det ble funnet på den publiserte forsiden.',
    'hint.cloudflare.2': 'Personvernsiden forteller det under «Besøkstelling» så lenge skriptet er der, så ingenting skjules for de besøkende.',
    'hint.cloudflare.3': 'Slik slår du det av: Cloudflares dashbord, domenet, Web Analytics, Manage RUM Settings, Disable. Cloudflare slår det ikke på igjen når det først er slått av.',
    'hint.orders.title': 'Oppbevaringen av bestillinger',
    'hint.orders.1': 'Vi er bokføringspliktige: en bedrift er bokføringspliktig etter bokføringsloven uansett størrelse, siden den leverer skattemelding for næringsinntekt eller mva-melding. En forening er det når den er regnskapspliktig (eiendeler over 20 millioner kroner eller mer enn 20 årsverk to år på rad, regnskapsloven § 1-2), leverer skattemelding for økonomisk virksomhet (omsetning over 70 000 kroner i året, 140 000 for en veldedig eller allmennyttig forening, skatteloven § 2-32) eller er registrert i Merverdiavgiftsregisteret (over 50 000 kroner på tolv måneder, 140 000 for en veldedig eller allmennyttig forening, merverdiavgiftsloven § 2-1). Da oppbevares salgsdokumentasjonen i fem år etter regnskapsårets slutt etter bokføringsloven § 13, for seg og uten annen bruk. Personvernsiden sier da det, og at e-postadressen, telefonnummeret og kommentaren slettes når bestillingen er gjort opp, slik Datatilsynet ber om; velg det der det er slik dere gjør.',
    'hint.orders.2': 'Et idrettslag i NIF: et lag i Norges idrettsforbund oppbevarer regnskapet i fem år etter regnskapsårets slutt etter NIFs lov § 2-11, uansett størrelse.',
    'hint.orders.3': 'I en fastsatt tid: en forening under alle grensene, der ingen lov krever at bestillingen oppbevares, beholder den bare så lenge formålet trenger (personvernforordningen artikkel 5 nr. 1 bokstav e); en som søker momskompensasjon, oppbevarer regnskapet i tre år (kompensasjonsforskriften § 15).',
    'hint.orders.4': 'Ikke bestemt: personvernsiden sier det og ber leseren ta kontakt.',
    'hint.orders.5': 'Grensene ble lest på Lovdata og idrettsforbundet.no 6. november 2026; utenfor Norge tilbys bare en fastsatt tid til landet er undersøkt.',
