    'settings.mapService': 'Karttjeneste',
    'tip.settings.mapService': 'Kartet et sted åpnes i når en besøkende trykker på det, for eksempel stedet for et arrangement i kalenderen. Det er bare en lenke: ingenting lastes fra tjenesten før den besøkende trykker',
    'settings.meetingHosts': 'Egne møteadresser',
    'tip.settings.meetingHosts': 'Adressene til egne videomøteservere, skilt med komma, for eksempel meet.example.org for en Jitsi-, Nextcloud Talk- eller BigBlueButton-server. En lenke til en av dem i et kalenderarrangement gir arrangementet «Bli med»-knappen. Zoom, Teams, Google Meet, Whereby, Webex, Proton Meet, kMeet, Element Call og meet.jit.si er kjent fra før',
    'mapService.osm': 'OpenStreetMap',
    'mapService.osm.note': 'Et fritt kart tegnet av frivillige over hele verden, drevet av den ideelle OpenStreetMap Foundation i Storbritannia. Ingen reklame og ingen profil av den besøkende. Finner adresser godt, men sjelden et lokale ved navn.',
    'mapService.google': 'Google Maps',
    'mapService.google.note': 'Laget av Google i USA. Finner de fleste lokaler ved navn. Betalt av reklame: søk logges og knyttes til Google-kontoen til en besøkende som er logget inn.',
    'mapService.apple': 'Apple Kart',
    'mapService.apple.note': 'Laget av Apple i USA. Finner lokaler ved navn og åpner Kart-appen på Apple-enheter. Apple sier at søk knyttes til en tilfeldig identifikator og ikke til en Apple-konto.',
    'mapService.duckduckgo': 'DuckDuckGo Maps',
    'mapService.duckduckgo.note': 'Laget av DuckDuckGo i USA, på kart fra Apple. DuckDuckGo sier at de ikke lagrer søk og ikke sender noe som identifiserer den besøkende videre til Apple.',
    'mapService.brave': 'Brave Maps',
    'mapService.brave.note': 'Laget av Brave Software i USA, på data fra OpenStreetMap med et eget stedsregister. Brave sier at de ikke bygger noen profil av dem som søker.',
    'mapService.norgeskart': 'Norgeskart',
    'mapService.norgeskart.note': 'Laget av Kartverket, en offentlig etat. De offisielle adressene og stedsnavnene i Norge, og ingenting utenfor. Ingen reklame. Passer best til adresser, turmål og større steder: lokaler, butikker og andre enkeltsteder finner det ikke ved navn.',
    'mapService.here': 'HERE WeGo',
    'mapService.here.note': 'Laget av HERE Technologies i Nederland, eid av blant andre tyske bilprodusenter. Egne kart, de samme mange biler navigerer etter, og finner lokaler ved navn. Et europeisk selskap under EUs personvernregler, og du trenger ingen konto for å søke.',
    'mapService.finn': 'FINN kart',
