    'preset.privacy.hint': 'Personvernsiden med overskriften, skrevet ut fra nettstedets innstillinger',
    'preset.terms.label': 'Kjøpsvilkår',
    'preset.terms.hint': 'Kjøpsvilkår for nettbutikken med angrerett og angreskjema, på nettstedets språk, til å fylle ut',
    'seed.terms.title': '<h1>Kjøpsvilkår</h1>',
    'seed.terms.intro': '<p>Disse vilkårene gjelder når du kjøper varer av {seller} i nettbutikken på dette nettstedet. Les dem før du bestiller.</p>',
    'seed.terms.glance': '<ul><li><strong>Angrerett</strong><br>14 dager fra du mottar varen</li><li><strong>Frakt</strong><br>[Skriv hva frakten koster]</li><li><strong>Betaling</strong><br>[Skriv hvordan det betales]</li><li><strong>Reklamasjon</strong><br>Minst to år</li></ul>',
    'seed.terms.agreement': '<h2>Avtalen</h2><p>Avtalen består av disse kjøpsvilkårene, opplysningene du får når du bestiller, og ordrebekreftelsen. Det vi har avtalt særskilt med deg, går foran. Kjøpet følger forbrukerkjøpsloven og angrerettloven, og vilkårene gir deg aldri færre rettigheter enn lovene gjør.</p>',
    'seed.terms.parties': '<h2>Partene</h2><p>Selger er {seller}, {details}. Kjøper er deg som bestiller varen.</p>',
    'seed.terms.prices': '<h2>Priser</h2><p>Prisene i nettbutikken er det du betaler for varen, med merverdiavgift der den gjelder. [Skriv hva frakt og eventuelle gebyrer koster, eller at de er med i prisen.] Du ser hele summen før du bestiller.</p>',
    'seed.terms.order': '<h2>Bestilling og bekreftelse</h2><p>Avtalen er bindende når du har sendt bestillingen. Du får en ordrebekreftelse på skjermen [og på e-post]. Se over at den stemmer med det du bestilte, og si fra til oss om noe er feil.</p>',
    'seed.terms.payment': '<h2>Betaling</h2><p>[Skriv hvordan det betales, for eksempel med Vipps, kort, PayPal eller faktura, og når beløpet trekkes.]</p>',
    'seed.terms.delivery': '<h2>Levering</h2><p>[Skriv hvordan og når varene sendes eller hentes, og hva det koster.] Varen er levert når du, eller den du har bedt om, har fått den. Fra da av har du risikoen for varen.</p>',
    'seed.terms.withdrawal': '<h2>Angrerett</h2><p>Du kan gå fra kjøpet uten å oppgi grunn innen 14 dager etter at du mottok varen. Gi oss beskjed før fristen går ut, på e-post eller med skjemaet nedenfor. Send varen tilbake innen 14 dager etter at du ga beskjed; du dekker kostnaden ved å returnere den [med mindre vi skriver noe annet her]. Vi betaler tilbake det du har betalt, også den vanlige frakten til deg, senest 14 dager etter at vi fikk beskjeden, men kan vente til vi har fått varen tilbake. [Skriv returadressen.]</p><p>Angreretten gjelder ikke for varer som er laget etter dine mål eller ønsker, eller som raskt blir dårlige, som mat.</p>',
    'seed.terms.defects': '<h2>Forsinkelse, mangler og reklamasjon</h2><p>Kommer varen for sent eller har den en mangel, har du rettighetene forbrukerkjøpsloven gir deg: du kan holde igjen betalingen, kreve at vi retter mangelen eller sender en ny vare, kreve prisavslag, heve kjøpet eller kreve erstatning. Si fra til oss innen rimelig tid etter at du oppdaget mangelen; to måneder er alltid i tide. Fristen er to år etter at du fikk varen, og fem år for varer som skal vare vesentlig lenger.</p>',
    'seed.terms.privacy': '<h2>Personopplysninger</h2><p>Opplysningene du gir når du bestiller, brukes til å levere bestillingen. Hvor lenge bestillingen oppbevares, og reglene som avgjør det, opplyser vi på personvernsiden vår eller på forespørsel.{privacyLink}</p>',
    'seed.terms.privacyLink': ' Les mer på <a href="{href}" data-urd-page="{page}">{title}</a>.',
    'seed.terms.disputes': '<h2>Klager og tvister</h2><p>Ta først kontakt med oss, så prøver vi å finne en løsning. Kommer vi ikke til enighet, kan du be Forbrukerrådet om mekling (forbrukerradet.no), og saken kan deretter gå til Forbrukerklageutvalget.</p>',
    'seed.terms.details': '[organisasjonsnummer, adresse, e-post og telefon]',
    'seed.terms.sellerPlaceholder': '[selgerens navn]',
