    'design.terms.contents': 'Delene listet i margen ved teksten ut fra overskriftene, til venstre eller høyre, og fulgt nedover mens man leser; på telefon foldes listen til én rad øverst.',
    'design.terms.glance': 'Tekstens første liste, der den står før den første overskriften, tegnet som kort, med de fete ordene i hvert punkt som etikett.',
