    'design.terms.clauses': 'Hver del nummerert, og avsnittene nummerert under den (7.1, 7.2), slik en kontrakt settes opp.',
    'seed.design.doc': '<h1>Kjøpsvilkår</h1><p>Disse vilkårene gjelder når du kjøper varer av Apeiron Linjeforening.</p><ul><li><strong>Angrerett</strong><br>14 dager fra du mottar varen</li><li><strong>Frakt</strong><br>79 kr, gratis over 500 kr</li><li><strong>Betaling</strong><br>Vipps eller kort</li><li><strong>Reklamasjon</strong><br>Minst to år</li></ul><h2>Partene</h2><p>Selger er Apeiron Linjeforening, Høgskoleringen 5, 7034 Trondheim. Kjøper er deg som bestiller varen.</p><h2>Priser</h2><p>Prisene er med merverdiavgift. Frakt koster 79 kr, og er gratis over 500 kr.</p><h2>Angrerett</h2><p>Du kan gå fra kjøpet uten å oppgi grunn innen 14 dager etter at du mottok varen.</p><p>Vi betaler tilbake det du har betalt senest 14 dager etter at vi fikk beskjeden.</p><h2>Reklamasjon</h2><p>Si fra innen rimelig tid etter at du oppdaget mangelen.</p>',
